2.34.1

The code statements that lead to the bug are:
static bool contains_pending_extent(struct btrfs_device *device, u64 *start, u64 len) {
    if (btrfs_find_first_extent_bit(&device->alloc_state, *start, &physical_start, &physical_end, CHUNK_ALLOCATED, NULL)) {
        if (in_range(physical_start, *start, len) || in_range(*start, physical_start, physical_end + 1 - physical_start)) {
            *start = physical_end + 1;
            return true;
        }
    }
    return false;
}
Reason:
This function only advanced `*start` past the first overlapping pending extent. When multiple non-consecutive pending extents existed within a candidate hole, the caller (`dev_extent_hole_check`) would then re‑check only the remaining range but could still overlap a later pending extent, leading to an EEXIST abort in `insert_dev_extents()`.

The code statements that fix the bug are:
static bool first_pending_extent(struct btrfs_device *device, u64 start, u64 len, u64 *pending_start, u64 *pending_end) {
    if (btrfs_find_first_extent_bit(&device->alloc_state, start, pending_start, pending_end, CHUNK_ALLOCATED, NULL)) {
        if (in_range(*pending_start, start, len) || in_range(start, *pending_start, *pending_end + 1 - *pending_start)) {
            return true;
        }
    }
    return false;
}
static bool find_hole_in_pending_extents(struct btrfs_device *device, u64 *start, u64 *len, u64 min_hole_size) {
    while (true) {
        if (first_pending_extent(device, *start, *len, &pending_start, &pending_end)) {
            if (pending_start <= *start) {
                *start = pending_end + 1;
                goto next;
            }
            *len = pending_start - *start;
            if (*len > max_hole_len) { max_hole_start = *start; max_hole_len = *len; }
            if (*len >= min_hole_size) break;
            *start = pending_end + 1;
            goto next;
        } else {
            if (*len > max_hole_len) { max_hole_start = *start; max_hole_len = *len; }
            break;
        }
next:
        if (*start > end) break;
        *len = end - *start + 1;
    }
    if (max_hole_len) { *start = max_hole_start; *len = max_hole_len; }
    else { *start = end + 1; *len = 0; }
    return max_hole_len >= min_hole_size;
}
Reason:
The new `find_hole_in_pending_extents()` loops through all pending extents in the candidate hole, correctly handling non‑consecutive ones by advancing past each and recording the largest free gap. This ensures the hole returned to the caller does not overlap any pending extent, preventing the EEXIST abort.

